  "implementation": "def solve(case):
    import json

    # Validate top-level fields
    if not isinstance(case, dict) or 'segments' not in case or 'budget' not in case:
        raise ValueError("case must contain 'segments' and 'budget'")

    segments = case['segments']
    budget = case['budget']

    if not isinstance(segments, list):
        raise ValueError("'segments' must be a list")
    if not isinstance(budget, int):
        raise ValueError("'budget' must be an integer")

    # Validate each segment and collect data
    seg_data = []  # (name, importance, min, capacity, original_index)
    for idx, seg in enumerate(segments):
        if not isinstance(seg, dict):
            raise ValueError(f"Segment at index {idx} is not a dict")
        for key in ('name', 'importance', 'minimum', 'capacity'):
            if key not in seg:
                raise ValueError(f"Segment at index {idx} missing '{key}'")
        name = seg['name']
        imp = seg['importance']
        mn = seg['minimum']
        cap = seg['capacity']
        if not all(isinstance(v, int) for v in (imp, mn, cap)):
            raise ValueError(f"Segment '{name}' has non-integer fields")
        if mn < 0 or cap < 0 or imp < 0:
            raise ValueError(f"Segment '{name}' has negative values")
        if mn > cap:
            raise ValueError(f"Segment '{name}' minimum ({mn}) exceeds capacity ({cap})")
        seg_data.append((name, imp, mn, cap, idx))

    total_min = sum(mn for _, _, mn, _, _ in seg_data)
    total_cap = sum(cap for _, _, _, cap, _ in seg_data)

    if budget < total_min or budget > total_cap:
        raise ValueError(f"Budget {budget} not in range [{total_min}, {total_cap}]")

    # Initialize allocation at minimum
    alloc = {name: mn for name, _, mn, _, _ in seg_data}
    remaining = budget - total_min

    # Helper to get utility for a segment (if not at capacity)
    def utility(seg_idx):
        name, imp, _, cap, _ = seg_data[seg_idx]
        cur = alloc[name]
        if cur >= cap:
            return -1  # sentinel, should never be chosen
        return imp / (cur + 1)  # next position

    # Track which segments still have room
    active = [i for i, (name, _, _, cap, _) in enumerate(seg_data) if alloc[name] < cap]

    while remaining > 0 and active:
        # find best utility, break ties by original index
        best_idx = min(active, key=lambda i: (-utility(i), i))
        name = seg_data[best_idx][0]
        alloc[name] += 1
        remaining -= 1
        # update active list: if now at capacity, remove
        if alloc[name] >= seg_data[best_idx][3]:
            active.remove(best_idx)

    if remaining > 0:
        # Should not happen if budget <= total_cap, but safety
        raise ValueError("Budget could not be fully allocated despite capacity check")

    # Build result
    result = {
        "allocations": alloc,
        "name_mapping": [name for name, _, _, _, _ in seg_data],
        "total": sum(alloc.values())
    }
    return result"
